#!/bin/bash
# Runs Stainless on the ASN1SCC Scala code generated by scripts/regen-asn1.sh.
#
#   scripts/verify-asn1.sh [name...]
#
# Only the generated functions (package asn1src) are verification targets;
# calls into the asn1scala runtime library are checked against the
# library's contracts. The summary of each run is written to
# asn1-formats/results/<name>.txt, the full Stainless output and JSON report
# to asn1-formats/build/<name>/.
#
#   STAINLESS        stainless launcher (default: stainless)
#   STAINLESS_CONF   stainless.conf (default: asn1-formats/stainless.conf)
#   TIMEOUT          per-VC timeout in seconds (default: 120)
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
STAINLESS="${STAINLESS:-stainless}"
CONF="${STAINLESS_CONF:-$ROOT/asn1-formats/stainless.conf}"
names=("$@")
if [ ${#names[@]} -eq 0 ]; then
  for pat in "$ROOT"/formats/*.hexpat; do names+=("$(basename "$pat" .hexpat)"); done
fi
mkdir -p "$ROOT/asn1-formats/results"
for name in "${names[@]}"; do
  build="$ROOT/asn1-formats/build/$name"
  [ -d "$build/scala" ] || { echo "$name: not built (run scripts/regen-asn1.sh)"; continue; }
  cd "$build/scala"
  fns=$(grep -ohE "^ *(@[a-zA-Z]+ )*def [A-Za-z0-9_]+" src/main/scala/asn1src/*.scala | grep -oE "def [A-Za-z0-9_]+" | sed 's/def //' | sort -u | paste -sd, -)
  srcs=$(ls src/main/scala/asn1scala/asn1jvm*.scala src/main/scala/asn1src/*.scala | grep -v "Codec_PER\|Codec_UPER")
  start=$(date +%s)
  "$STAINLESS" $srcs --config-file="$CONF" --timeout="${TIMEOUT:-120}" \
    --functions="$fns" --json="$build/stainless-report.json" > "$build/stainless.log" 2>&1
  status=$?
  end=$(date +%s)
  sed 's/\x1b\[[0-9;]*m//g' "$build/stainless.log" | tr '\r' '\n' > "$build/stainless.txt"
  {
    echo "format: $name"
    echo "stainless exit status: $status"
    echo "wall time: $((end - start)) s"
    grep -a -E "total: [0-9]+" "$build/stainless.txt" | tail -1 | sed 's/^.*\(total:\)/\1/; s/[^0-9a-z:. ()]*$//'
    echo
    echo "VCs that are not valid:"
    grep -a -E "^\[.*\] *(.*) *(invalid|unknown|timeout)" "$build/stainless.txt" | head -100
  } > "$ROOT/asn1-formats/results/$name.txt"
  head -4 "$ROOT/asn1-formats/results/$name.txt"
done
